"""Generate backend/mcp/PROMPT.md from src/maxergy_mcp/instructions.py.

Usage (from backend/mcp):
    uv run python scripts/gen_prompt.py          # regenerate
    uv run python scripts/gen_prompt.py --check  # exit 1 if PROMPT.md is out of date
"""

from __future__ import annotations

import sys
from pathlib import Path

from maxergy_mcp.instructions import ONBOARDING_SCRIPT, SERVER_INSTRUCTIONS

PROMPT_FILE = Path(__file__).resolve().parents[1] / "PROMPT.md"


def render() -> str:
    return (
        "# MAXergy Advisor — system prompt\n\n"
        "<!-- GENERATED by scripts/gen_prompt.py from src/maxergy_mcp/instructions.py. "
        "Do not edit by hand. -->\n\n"
        "Use this as the system prompt for an LLM that has the MAXergy MCP tools connected but\n"
        "does not receive the server instructions automatically. MCP clients that support server\n"
        "instructions and prompts get the same text from the server (`instructions`,\n"
        "`start_advisor`, prompt `maxergy_advisor`).\n\n"
        "## Server instructions\n\n"
        f"{SERVER_INSTRUCTIONS}\n\n"
        "## Onboarding script\n\n"
        f"{ONBOARDING_SCRIPT}\n"
    )


def main() -> int:
    content = render()
    if "--check" in sys.argv:
        if PROMPT_FILE.read_text(encoding="utf-8") != content:
            print("PROMPT.md is out of date — run: uv run python scripts/gen_prompt.py")
            return 1
        print("PROMPT.md is up to date")
        return 0
    PROMPT_FILE.write_text(content, encoding="utf-8")
    print(f"wrote {PROMPT_FILE}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
